1: import { readFileSync } from 'node:fs';
2: import { resolve } from 'node:path';
3: import { PGlite } from '@electric-sql/pglite';
4: import { afterEach, describe, expect, it } from 'vitest';
5: 
6: const rls = readFileSync(resolve(import.meta.dirname, '../../../server/sql/info-ssot-rls.sql'), 'utf8');
7: const ROW_COUNT = 6702;
8: 
9: let db;
10: 
11: afterEach(async () => {
12:   await db?.close();
13:   db = undefined;
14: });
15: 
16: async function explainList() {
17:   await db.exec(`
18:     SELECT set_config('app.role', 'member', true);
19:     SELECT set_config('app.project_codes', 'atlas', true);
20:     SELECT set_config('app.clearance', 'internal', true);
21:   `);
22:   const result = await db.query(`EXPLAIN (ANALYZE, FORMAT JSON)
23:     SELECT id FROM public.graph_entities
24:     ORDER BY updated_at DESC, id DESC
25:     LIMIT 50`);
26:   return result.rows[0]['QUERY PLAN'][0];
27: }
28: 
29: describe('graph entity visibility plan', () => {
30:   it('measures the non-inlined function against the schema-qualified replacement', async () => {
31:     db = new PGlite();
32:     await db.exec(`
33:       CREATE TABLE public.projects (
34:         id text PRIMARY KEY,
35:         code text NOT NULL UNIQUE
36:       );
37:       CREATE TABLE public.graph_entities (
38:         id text PRIMARY KEY,
39:         entity_type text NOT NULL,
40:         project_id text,
41:         payload jsonb NOT NULL DEFAULT '{}'::jsonb,
42:         role_min text,
43:         sensitivity text,
44:         lifecycle_status text NOT NULL DEFAULT 'active',
45:         updated_at timestamptz NOT NULL
46:       );
47:       CREATE TABLE public.graph_edges (
48:         id text PRIMARY KEY,
49:         from_id text NOT NULL,
50:         project_id text NOT NULL,
51:         rel_type text NOT NULL,
52:         role_min text,
53:         sensitivity text,
54:         lifecycle_status text NOT NULL
55:       );
56:       INSERT INTO public.projects (id, code) VALUES ('project-atlas', 'atlas');
57:       INSERT INTO public.graph_entities (id, entity_type, project_id, role_min, sensitivity, updated_at)
58:       SELECT 'e' || gs::text, 'objective', 'project-atlas', 'member', 'internal',
59:              timestamptz '2026-10-13' - (gs || ' seconds')::interval
60:       FROM generate_series(1, ${ROW_COUNT}) AS gs;
61:       CREATE INDEX graph_entities_updated_at_desc_idx ON public.graph_entities (updated_at DESC);
62:       CREATE ROLE app_runtime NOLOGIN;
63:       GRANT SELECT ON public.projects TO app_runtime;
64:       GRANT SELECT ON public.graph_entities TO app_runtime;
65:       GRANT SELECT ON public.graph_edges TO app_runtime;
66:       CREATE OR REPLACE FUNCTION public.app_foundation_row_visible(
67:         entity_id text, entity_type text, project_id text, role_min text, sensitivity text
68:       ) RETURNS boolean
69:       LANGUAGE sql STABLE
70:       SET search_path = pg_catalog, public
71:       AS $body$ SELECT TRUE $body$;
72:       ALTER TABLE public.graph_entities ENABLE ROW LEVEL SECURITY;
73:       ALTER TABLE public.graph_entities FORCE ROW LEVEL SECURITY;
74:       CREATE POLICY info_graph_entities_select ON public.graph_entities
75:         FOR SELECT USING (public.app_foundation_row_visible(id, entity_type, project_id, role_min, sensitivity));
76:     `);
77: 
78:     await db.exec('BEGIN');
79:     await db.exec('SET ROLE app_runtime');
80:     const before = await explainList();
81:     await db.exec('ROLLBACK');
82: 
83:     await db.exec(rls);
84:     const config = await db.query(`
85:       SELECT proconfig, proleakproof
86:       FROM pg_proc
87:       JOIN pg_namespace ON pg_namespace.oid = pg_proc.pronamespace
88:       WHERE nspname = 'public' AND proname = 'app_foundation_row_visible'
89:     `);
90:     expect(config.rows[0].proconfig).toBeNull();
91:     expect(config.rows[0].proleakproof).toBe(false);
92: 
93:     await db.exec('BEGIN');
94:     await db.exec("SELECT set_config('jit', 'off', true)");
95:     await db.exec('SET ROLE app_runtime');
96:     const after = await explainList();
97:     await db.exec('ROLLBACK');
98: 
99:     const beforeText = JSON.stringify(before);
100:     const afterText = JSON.stringify(after);
101:     const scanOf = (plan) => {
102:       if (!plan) return null;
103:       if (plan['Node Type'] === 'Index Scan' || plan['Node Type'] === 'Seq Scan') return plan;
104:       return (plan.Plans ?? []).map(scanOf).find(Boolean) ?? null;
105:     };
106:     const beforeScan = scanOf(before.Plan);
107:     const afterScan = scanOf(after.Plan);
108:     console.info(JSON.stringify({
109:       rows: ROW_COUNT,
110:       engine: 'pglite',
111:       before_ms: before['Execution Time'],
112:       after_ms: after['Execution Time'],
113:       before_limit_plan_rows: before.Plan['Plan Rows'],
114:       after_limit_plan_rows: after.Plan['Plan Rows'],
115:       before_scan_plan_rows: beforeScan?.['Plan Rows'] ?? null,
116:       after_scan_plan_rows: afterScan?.['Plan Rows'] ?? null,
117:       before_scan_actual_rows: beforeScan?.['Actual Rows'] ?? null,
118:       after_scan_actual_rows: afterScan?.['Actual Rows'] ?? null,
119:       before_actual_rows: before.Plan['Actual Rows'],
120:       after_actual_rows: after.Plan['Actual Rows'],
121:       before_names_function: beforeText.includes('app_foundation_row_visible'),
122:       after_names_function: afterText.includes('app_foundation_row_visible')
123:     }));
124: 
125:     expect(beforeText).toContain('app_foundation_row_visible');
126:     expect(afterText).not.toContain('app_foundation_row_visible');
127:     expect(after.Plan['Actual Rows']).toBe(50);
128:   }, 120000);
129: });

